	/* @Override */
	public void invalidateCache(bool all) {
		languageStore.invalidateCache();
		platformStore.invalidateCache();
		rangeMappingStore.invalidateCache();
		languagesByLanguage.clear();
		platformsByCompiler.clear();
		try {
			loadLanguages();
			// TODO: Or IMMUTABLE, if that was the original, and supported
			loadPlatforms(OpenMode.UPDATE, TaskMonitor.DUMMY);
			loadPlatformMappings();
		}
		catch (Exception e) when (e is IOException or VersionException or CancelledException) {
			throw new AssertionError(e);
		}
